//! The Rust code of a message catalog: for each message, 1 entry per language,
//! with the source text at index 0 and then the languages of the bundle in
//! their order.

use crate::bundle::Bundle;
use crate::plural_rule::PluralRule;
use crate::scan::Messages;

const HEADER: &str = "\
// Generated by sc-message-catalog from the `ctr!` calls of the crate and its
// `.po` files. Each message holds 1 entry per language, in the order of the
// bundle with the source text first; the entry is `None` where a language has
// no translation. Do not edit.
";

const SINGULAR_TYPE: &str = "
#[derive(Debug)]
pub(crate) struct Message {
    context: &'static str,
    id: &'static str,
    pub(crate) translations: &'static [Option<&'static str>],
}
";

const SINGULAR_LOOKUP: &str = "
pub(crate) const fn message(context: &str, id: &str) -> Option<&'static Message> {
    let mut index = 0;
    while index < MESSAGES.len() {
        let message = &MESSAGES[index];
        if same(message.context, context) && same(message.id, id) {
            return Some(message);
        }
        index += 1;
    }
    None
}
";

const PLURAL_TYPE: &str = "
#[derive(Debug)]
pub(crate) struct PluralMessage {
    context: &'static str,
    singular: &'static str,
    plural: &'static str,
    pub(crate) translations: &'static [Option<&'static [&'static str]>],
}
";

const PLURAL_LOOKUP: &str = "
pub(crate) const fn plural_message(
    context: &str,
    singular: &str,
    plural: &str,
) -> Option<&'static PluralMessage> {
    let mut index = 0;
    while index < PLURAL_MESSAGES.len() {
        let message = &PLURAL_MESSAGES[index];
        if same(message.context, context)
            && same(message.singular, singular)
            && same(message.plural, plural)
        {
            return Some(message);
        }
        index += 1;
    }
    None
}
";

const SAME: &str = "
const fn same(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut index = 0;
    while index < a.len() {
        if a[index] != b[index] {
            return false;
        }
        index += 1;
    }
    true
}
";

/// Writes the catalog of `messages`, with their translations in the languages
/// of `bundle`. Each part is written only when a message needs it, so the code
/// has no unused item. The `ctr!` macro of the crate must reach the module that
/// includes the code.
pub fn catalog_code(bundle: &Bundle, messages: &Messages) -> String {
    let singular: Vec<(&str, &str)> = messages.singular().collect();
    let plural: Vec<(&str, &str, &str)> = messages.plural().collect();
    let mut code = String::from(HEADER);
    if !singular.is_empty() {
        code.push_str(SINGULAR_TYPE);
        code.push_str(&singular_messages(bundle, &singular));
        code.push_str(SINGULAR_LOOKUP);
    }
    if !plural.is_empty() {
        code.push_str(PLURAL_TYPE);
        code.push_str(&plural_messages(bundle, &plural));
        code.push_str(PLURAL_LOOKUP);
        code.push_str(&plural_rules(bundle));
    }
    code.push_str(&languages(bundle));
    if !singular.is_empty() || !plural.is_empty() {
        code.push_str(SAME);
    }
    code
}

fn singular_messages(bundle: &Bundle, messages: &[(&str, &str)]) -> String {
    let mut code = String::from("\nconst MESSAGES: &[Message] = &[\n");
    for &(context, id) in messages {
        let translations: Vec<String> = std::iter::once(Some(id.to_owned()))
            .chain(
                bundle
                    .languages()
                    .iter()
                    .map(|language| language.singular(context, id)),
            )
            .map(|translation| option(translation.map(|text| format!("{text:?}"))))
            .collect();
        code.push_str(&format!(
            "    Message {{\n        context: {context:?},\n        id: {id:?},\n        \
             translations: &[{}],\n    }},\n",
            translations.join(", ")
        ));
    }
    code.push_str("];\n");
    code
}

fn plural_messages(bundle: &Bundle, messages: &[(&str, &str, &str)]) -> String {
    let mut code = String::from("\nconst PLURAL_MESSAGES: &[PluralMessage] = &[\n");
    for &(context, singular, plural) in messages {
        let source = vec![singular.to_owned(), plural.to_owned()];
        let translations: Vec<String> = std::iter::once(Some(source))
            .chain(
                bundle
                    .languages()
                    .iter()
                    .map(|language| language.plural(context, singular)),
            )
            .map(|forms| option(forms.map(|forms| forms_literal(&forms))))
            .collect();
        code.push_str(&format!(
            "    PluralMessage {{\n        context: {context:?},\n        singular: {singular:?},\n        \
             plural: {plural:?},\n        translations: &[{}],\n    }},\n",
            translations.join(", ")
        ));
    }
    code.push_str("];\n");
    code
}

/// 1 rule per language, the rule of the source text first.
fn plural_rules(bundle: &Bundle) -> String {
    let source = PluralRule::singular_for_one();
    let rules: Vec<&PluralRule> = std::iter::once(&source)
        .chain(
            bundle
                .languages()
                .iter()
                .map(|language| language.plural_rule()),
        )
        .collect();
    let names: Vec<String> = (0..rules.len())
        .map(|index| format!("Some(plural_rule_{index})"))
        .collect();
    let mut code = format!(
        "\npub(crate) type PluralRule = fn(i32) -> usize;\n\n\
         pub(crate) const PLURAL_RULES: &[Option<PluralRule>] = &[{}];\n",
        names.join(", ")
    );
    for (index, rule) in rules.iter().enumerate() {
        code.push('\n');
        code.push_str(&rule.write_fn(&format!("plural_rule_{index}")));
    }
    code
}

/// The codes of the languages, the source text (`""`) first, for the tests of
/// the crate that includes the code.
fn languages(bundle: &Bundle) -> String {
    let codes: Vec<String> = std::iter::once("")
        .chain(bundle.languages().iter().map(|language| language.code()))
        .map(|code| format!("{code:?}"))
        .collect();
    format!(
        "\n#[cfg(test)]\npub(crate) const LANGUAGES: &[&str] = &[{}];\n",
        codes.join(", ")
    )
}

fn option(value: Option<String>) -> String {
    match value {
        Some(value) => format!("Some({value})"),
        None => "None".to_owned(),
    }
}

fn forms_literal(forms: &[String]) -> String {
    let forms: Vec<String> = forms.iter().map(|form| format!("{form:?}")).collect();
    format!("&[{}]", forms.join(", "))
}
